mapper.select:
SELECT COUNT(*)
FROM scheduled_messages
WHERE persona_id = #{personaId}
  AND is_sent = 0
  AND (
      (scheduled_time >= #{nowTime} AND scheduled_time <= #{oneHourLater})
      OR
      (#{oneHourLater} < #{nowTime}
       AND (scheduled_time >= #{nowTime} OR scheduled_time <= #{oneHourLater}))
  )

SELECT COUNT(*)
FROM scheduled_messages
WHERE persona_id = #{personaId}
  AND is_sent = 0
  AND scheduled_time BETWEEN #{minuteStart} AND #{minuteEnd}

SELECT *
FROM scheduled_messages
WHERE persona_id = #{personaId}
  AND is_sent = 0
  AND scheduled_time <= #{nowTime}
  AND scheduled_time > #{oneSecondAgo}
ORDER BY scheduled_time ASC
